#!/usr/bin/env python
# ── GENERATED by matsci-knowledge-base build/build_plugin.py — DO NOT EDIT (真源见 plugin.yaml) ──
# -*- coding: utf-8 -*-
"""专项普查：lit-watch 模板的「SI 判定：不适用本件——提取件无分页标记」尾注。

某轮质检报该尾注在 wiki/ 下见于百页量级，属**批量失效声明**
（本可判定，却被写成不可判定）。本脚本量化其规模并核对真伪。

用法:
    python tools/qc_si_template_sweep.py              # 干跑
    python tools/qc_si_template_sweep.py --selftest   # 校验器自检
"""
import sys, os, re, glob, json, argparse


ROOT = os.path.dirname(os.path.dirname(os.path.abspath(__file__)))
os.chdir(ROOT)
sys.path.insert(0, "tools")
from kb_lib import read_text, qc_work_dir  # noqa: E402
from kb_lib import console_encoding
console_encoding()

TEMPLATE = re.compile(
    r"SI 判定[：:]?\s*不适用本件|不适用本件[—\-—]*提取件无|提取件无\s*`?<!--")

# 分页标记：`<!-- page N -->` 与 `<!-- SM page N -->` **都要匹配**（前缀可选——
# 写成必选会漏掉标准形态，qc_si_sweep 的 selftest 已抓到该过度收紧）。
# 页号 `\d+` 为**必选**：无号占位串 `<!-- page -->` 不是分页标记。
PAGE_MARK_RE = re.compile(r"<!--\s*(?:[A-Za-z]+\s+)?page\s*\d+[^>]*-->", re.I)


def count_markers(text):
    return len(PAGE_MARK_RE.findall(text))


def markers(raw):
    if not os.path.exists(raw):
        return None
    if raw.lower().endswith(".pdf"):
        try:
            if open(raw, "rb").read(5).startswith(b"%PDF"):
                return None
        except Exception:
            return None
    try:
        rt = read_text(raw)
    except Exception:
        return None
    return count_markers(rt)


def sweep():
    rows = []
    for f in sorted(glob.glob("wiki/**/*.md", recursive=True)):
        t = read_text(f)
        m = TEMPLATE.search(t)
        if not m:
            continue
        fm = t[: t.find("\n---", 3)]
        raws = [r.replace(os.sep, "/").replace("\\", "/")
                for r in re.findall(r"\[\[(raw/[^\]|]+)", fm)]
        mx = 0
        for r in raws:
            n = markers(r)
            if n:
                mx = max(mx, n)
        rows.append({"page": os.path.basename(f)[:-3],
                     "rel": os.path.relpath(f, ".").replace(os.sep, "/"),
                     "markers": mx})
    return rows


def selftest():
    """校验器自检：已知答案反算（正例 + 反例）。"""
    ok = True
    # 正例：模板三种写法必须命中
    for s, want in (("SI 判定：不适用本件", True),
                    ("不适用本件——提取件无分页", True),
                    ("提取件无 `<!--", True)):
        got = bool(TEMPLATE.search(s))
        print(f"  [{'ok' if got == want else 'FAIL'}] 模板正例命中: {s[:18]!r} -> {got}")
        ok = ok and got == want
    # 反例：普通文本不得命中
    got = bool(TEMPLATE.search("本件包含 SI，页数 12。"))
    print(f"  [{'ok' if not got else 'FAIL'}] 反例 普通文本不命中")
    ok = ok and not got
    # 正例/反例：分页标记计数（标准形态与 SM 形态都必须数到）
    for txt, want, label in (("<!-- SM page 3 -->", 1, "SM page 形态"),
                             ("<!-- page 7 -->", 1, "标准 page 形态"),
                             ("没有标记", 0, "无标记")):
        got = count_markers(txt)
        print(f"  [{'ok' if got == want else 'FAIL'}] {label} -> {got} (期望 {want})")
        ok = ok and got == want
    # 全库扫描：空库 0 页是合法状态；命中能力由下方合成库夹具钉住
    rows = sweep()
    print(f"  [info] 全库扫描跑通 -> {len(rows)} 页含模板尾注（空库 0 属合法）")
    # ---- 夹具：合成库正例（只对临时目录，绝不碰真库）----
    import tempfile, shutil
    _old_cwd = os.getcwd()
    _tmp = tempfile.mkdtemp(prefix="qc_si_template_sweep_selftest_")
    try:
        os.makedirs(os.path.join(_tmp, "wiki", "sources"), exist_ok=True)
        os.makedirs(os.path.join(_tmp, "raw", "text"), exist_ok=True)
        with open(os.path.join(_tmp, "raw", "text", "F-提取件.md"), "w",
                  encoding="utf-8", newline="\n") as fh:
            fh.write("# 提取件\n<!-- page 1 -->\n正文\n<!-- SM page 2 -->\n补充材料\n")
        with open(os.path.join(_tmp, "wiki", "sources", "F-模板尾注.md"), "w",
                  encoding="utf-8", newline="\n") as fh:
            fh.write('---\ntype: source\nsources:\n  - "[[raw/text/F-提取件.md]]"\n'
                     '---\n\n# F\n\nSI 判定：不适用本件——提取件无分页标记。\n')
        with open(os.path.join(_tmp, "raw", "text", "G-仅摘要.md"), "w",
                  encoding="utf-8", newline="\n") as fh:
            fh.write("# 提取件\n只剩摘要，没有分页标记。\n")
        with open(os.path.join(_tmp, "wiki", "sources", "G-确无.md"), "w",
                  encoding="utf-8", newline="\n") as fh:
            fh.write('---\ntype: source\nsources:\n  - "[[raw/text/G-仅摘要.md]]"\n'
                     '---\n\n# G\n\nSI 判定：不适用本件——提取件无分页标记。\n')
        os.chdir(_tmp)
        rows2 = sweep()
        hit = [r for r in rows2 if r["page"] == "F-模板尾注"]
        none = [r for r in rows2 if r["page"] == "G-确无"]
        c_fix = (len(rows2) == 2 and len(hit) == 1 and len(none) == 1
                 and hit[0]["markers"] == 2 and none[0]["markers"] == 0)
        print(f"  [{'ok' if c_fix else 'FAIL'}] 夹具 正例 sweep 命中模板尾注页"
              f"且标记计数正确 -> {[(r['page'], r['markers']) for r in rows2]}")
        ok = ok and c_fix
    except Exception as e:                                    # noqa: BLE001
        print(f"  [FAIL] 夹具异常: {type(e).__name__}: {e}")
        ok = False
    finally:
        os.chdir(_old_cwd)
        shutil.rmtree(_tmp, ignore_errors=True)
    # 正例：写盘目标在库根、未落归档
    wd = qc_work_dir(create=True)
    safe = "_archive" not in wd.replace("/", "\\")
    print(f"  [{'ok' if safe else 'FAIL'}] 写盘目标在库根、未落归档 -> {wd}")
    ok = ok and safe
    print("=== selftest", "PASS ===" if ok else "FAIL ===")
    return 0 if ok else 1


def main():
    ap = argparse.ArgumentParser(description="lit-watch SI 模板尾注核查")
    ap.add_argument("--selftest", action="store_true", help="校验器自检")
    a = ap.parse_args()
    if a.selftest:
        return selftest()

    rows = sweep()
    bad = [r for r in rows if r["markers"] > 0]
    ok_rows = [r for r in rows if r["markers"] == 0]
    print("含 lit-watch「不适用本件」模板尾注的页面: %d" % len(rows))
    print("  🔴 实测有分页标记（声明失效）: %d" % len(bad))
    print("  ✅ 实测确无标记（声明成立）  : %d" % len(ok_rows))
    print()
    for r in sorted(bad, key=lambda x: -x["markers"])[:40]:
        print("   %4d 个标记  %s" % (r["markers"], r["page"]))
    if len(bad) > 40:
        print("   ... 另有 %d 页" % (len(bad) - 40))
    out = os.path.join(qc_work_dir(create=True), "si_template_sweep.json")
    json.dump(rows, open(out, "w", encoding="utf-8"),
              ensure_ascii=False, indent=1)
    print("\n清单 -> %s" % out)
    return 0


if __name__ == "__main__":
    sys.exit(main())
